constexpr Color orbit{53,91,126,125},text{220,234,248,245},muted{143,173,203,230},border{74,128,176,235};
void overlay_fill(DrawList&o,UiRect b,Color c){o.overlay.emplace_back(FilledRectangle{b,c});}
void overlay_stroke(DrawList&o,UiRect b,Color c){o.overlay.emplace_back(StrokedRectangle{b,c});}
void overlay_text(DrawList&o,float x,float y,std::string value,Color c,int size=15,float wrap=0,std::optional<UiRect> clip=std::nullopt){o.overlay.emplace_back(Text{{x,y},std::move(value),c,size,wrap,clip});}
std::string number(double value,int precision=2){std::ostringstream out;out<<std::fixed<<std::setprecision(precision)<<value;return out.str();}
Color visual_color(NativeSystemBodyVisualClass value){switch(value){case NativeSystemBodyVisualClass::rocky:return {178,143,115,255};case NativeSystemBodyVisualClass::oceanic:return {70,152,213,255};case NativeSystemBodyVisualClass::frozen:return {171,217,235,255};case NativeSystemBodyVisualClass::hot_rocky:return {222,116,66,255};case NativeSystemBodyVisualClass::gas_giant:return {211,167,114,255};case NativeSystemBodyVisualClass::ice_giant:return {111,190,215,255};case NativeSystemBodyVisualClass::moon:return {180,184,190,255};case NativeSystemBodyVisualClass::unknown_moon:return {112,137,160,255};default:return {94,132,166,255};}}
Color star_color(std::optional<StellarClass> value){if(!value)return {135,150,174,235};switch(*value){case StellarClass::MRedDwarf:return {255,119,76,230};case StellarClass::KOrangeDwarf:return {255,167,92,235};case StellarClass::GYellowDwarf:return {255,230,150,245};case StellarClass::FYellowWhiteDwarf:return {255,247,215,245};case StellarClass::AWhiteStar:return {225,236,255,245};case StellarClass::HotBlueStar:return {126,174,255,245};case StellarClass::Giant:return {255,142,88,245};case StellarClass::WhiteDwarf:return {221,236,255,235};case StellarClass::NeutronStar:return {133,218,255,250};case StellarClass::BlackHole:return {126,92,178,230};case StellarClass::Protostar:return {255,112,160,230};case StellarClass::Pulsar:return {91,229,255,250};}return {135,150,174,235};}
std::string kind_name(PlanetaryBodyKind value){switch(value){case PlanetaryBodyKind::Moon:return "Moon";case PlanetaryBodyKind::DwarfPlanet:return "Dwarf planet";default:return "Planet";}}
std::string grouped(std::int64_t value){auto digits=std::to_string(value);for(auto at=static_cast<std::ptrdiff_t>(digits.size())-3;at>0;at-=3)digits.insert(static_cast<std::size_t>(at),1,',');return digits;}
// MetricFormat port — SI display strings gated on the detailed-survey flag
// (NativeSystemBody::details presence equals the reference's
// HasDetailedEnvironment).
std::string metric_radius(double earth_radii,bool confirmed){if(!confirmed||!std::isfinite(earth_radii)||earth_radii<=0.)return "Unconfirmed";return grouped(std::llround(earth_radii*6371.))+" km";}
std::string metric_mass(double earth_masses,bool confirmed){if(!confirmed||!std::isfinite(earth_masses)||earth_masses<0.)return "Unconfirmed";const auto kilograms=earth_masses*5.9722e24;if(kilograms<1e6)return grouped(std::llround(kilograms))+" kg";const auto exponent=static_cast<int>(std::floor(std::log10(kilograms)));auto coefficient=number(kilograms/std::pow(10.,exponent),3);while(coefficient.size()>1&&coefficient.back()=='0')coefficient.pop_back();if(!coefficient.empty()&&coefficient.back()=='.')coefficient.pop_back();return coefficient+" × 10^"+std::to_string(exponent)+" kg";}
std::string metric_gravity(double gravity_g,bool confirmed){if(!confirmed||!std::isfinite(gravity_g)||gravity_g<0.)return "Unconfirmed";return number(gravity_g*9.80665,2)+" m/s²";}
std::string metric_temperature(double kelvin,bool confirmed){if(!confirmed||!std::isfinite(kelvin)||kelvin<0.)return "Unconfirmed";return number(kelvin,0)+" K";}
std::string metric_pressure(double kilo_pascals,bool confirmed){if(!confirmed||!std::isfinite(kilo_pascals)||kilo_pascals<0.)return "Unconfirmed";return number(kilo_pascals,2)+" kPa";}
std::string atmosphere_name(PlanetaryAtmosphereRegime value){switch(value){case PlanetaryAtmosphereRegime::OxygenNitrogen:return "Oxygen / nitrogen";case PlanetaryAtmosphereRegime::OxygenRich:return "Oxygen rich";case PlanetaryAtmosphereRegime::CarbonDioxideRich:return "Carbon dioxide";case PlanetaryAtmosphereRegime::Reducing:return "Reducing";case PlanetaryAtmosphereRegime::Inert:return "Inert";case PlanetaryAtmosphereRegime::Vacuum:return "Vacuum";case PlanetaryAtmosphereRegime::Other:return "Other";}return "Unconfirmed";}
std::uint32_t mix(std::uint32_t value){value^=value>>16;value*=0x7feb352du;value^=value>>15;value*=0x846ca68bu;return value^(value>>16);}
std::optional<std::pair<Point,Point>> clipped(Point a,Point b,UiRect r){float t0=0,t1=1;const float dx=b.x-a.x,dy=b.y-a.y;const std::array p{-dx,dx,-dy,dy};const std::array q{a.x-r.x,r.x+r.width-a.x,a.y-r.y,r.y+r.height-a.y};for(std::size_t i=0;i<p.size();++i){if(p[i]==0){if(q[i]<0)return std::nullopt;continue;}const auto t=q[i]/p[i];if(p[i]<0)t0=std::max(t0,t);else t1=std::min(t1,t);if(t0>t1)return std::nullopt;}return std::pair{Point{a.x+t0*dx,a.y+t0*dy},Point{a.x+t1*dx,a.y+t1*dy}};}
bool intersects(UiRect r,float x,float y,float radius){return x+radius>=r.x&&x-radius<=r.x+r.width&&y+radius>=r.y&&y-radius<=r.y+r.height;}
bool contains_disc(UiRect r,Point center,float radius){return center.x-radius>=r.x&&center.x+radius<=r.x+r.width&&center.y-radius>=r.y&&center.y+radius<=r.y+r.height;}
std::string fleet_role(FleetRole role){switch(role){case FleetRole::Scout:return "SC";case FleetRole::Science:return "RS";case FleetRole::Colony:return "CO";case FleetRole::Military:return "MI";case FleetRole::Logistics:return "LG";}return "FL";}
Color infrastructure_color(NativeInfrastructureState state){switch(state){case NativeInfrastructureState::complete:return {94,209,191,255};case NativeInfrastructureState::active:return {89,207,250,255};case NativeInfrastructureState::available:return {232,181,92,255};default:return {140,151,168,255};}}
const char*infrastructure_state_name(NativeInfrastructureState state){switch(state){case NativeInfrastructureState::complete:return "COMPLETE";case NativeInfrastructureState::active:return "ACTIVE";case NativeInfrastructureState::available:return "AVAILABLE";default:return "LOCKED";}}
std::string infrastructure_label(std::string_view label){constexpr std::string_view prefix="Orbital ";if(label.starts_with(prefix))label.remove_prefix(prefix.size());std::string out(label);for(auto&c:out)c=static_cast<char>(std::toupper(static_cast<unsigned char>(c)));return out;}
std::string lane_label(const NativeLocalLaneMarker&lane){if(!lane.known_label)return "????";if(!lane.known_length_light_years)return *lane.known_label;return *lane.known_label+"  "+number(*lane.known_length_light_years,1)+" ly";}
SystemSpatialViewport workspace_fit(const SystemSpatialSnapshot&spatial,int width,int height){const auto layout=SystemWorkspaceLayout::for_viewport(width,height);const auto&field=layout.world_field;const auto center_x=field.x+field.width*.5f,center_y=field.y+field.height*.5f;const auto half_extent=std::max(1.f,std::min(field.width,field.height)*.5f-82.f);const auto scale=std::clamp(half_extent/(spatial.design_radius*local_chart_render_radius_factor),.01f,1.15f);return {center_x,center_y,scale};}
double presentation_seconds(){static const auto epoch=std::chrono::steady_clock::now();return std::chrono::duration<double>(std::chrono::steady_clock::now()-epoch).count();}
